function B(f){let m=f.querySelector("video"),A=f.querySelector("[data-recording-title]");for(let j of document.querySelectorAll("a[data-recording]"))j.addEventListener("click",(q)=>{if(q.metaKey||q.ctrlKey||q.shiftKey)return;q.preventDefault(),A.textContent=j.dataset.title,m.style.objectPosition=j.dataset.focus,f.showModal(),m.src=j.href,m.play().catch((x)=>{if(x.name!=="AbortError")throw x})});f.addEventListener("click",(j)=>{if(j.target===f)f.close()}),f.addEventListener("close",()=>{if(f.open)return;m.removeAttribute("src"),m.load()})}var z=document.querySelector("[data-recording-player]");if(z)B(z);
